import type { EmailMessage } from "@/email/email-message.ts";
import { INVITATION_EMAIL_COPY } from "@/ui/copy/invitations.ts";

// URLs are generated by the site; escape their query delimiter for HTML.
function invitationEmail({
  to,
  url,
  idempotencyKey,
}: {
  readonly to: string;
  readonly url: string;
  readonly idempotencyKey: string;
}): EmailMessage {
  const { subject, intro, expiry } = INVITATION_EMAIL_COPY;
  const escaped = url
    .replaceAll("&", "&amp;")
    .replaceAll('"', "&quot;")
    .replaceAll("<", "&lt;")
    .replaceAll(">", "&gt;")
    .replaceAll("'", "&#39;");
  return {
    to,
    subject,
    text: `${intro}\n\n${url}\n\n${expiry}`,
    html: `<p>${intro}</p><p><a href="${escaped}">${escaped}</a></p><p>${expiry}</p>`,
    idempotencyKey,
  };
}

export { invitationEmail };
